// Title: Saving an Aspose.Cells workbook with a modified column chart to a MemoryStream for cloud storage in C#
// Common Searches: how to export an Aspose.Cells workbook with a chart to a MemoryStream in C# | upload Excel file generated by Aspose.Cells to Azure Blob storage after chart data changes | save Aspose.Cells workbook to a stream for remote cloud storage using .NET | C# Aspose.Cells modify chart series then write workbook to byte array | convert Aspose.Cells chart‑enhanced workbook to a stream for HTTP upload
// Tags: Aspose.Cells save workbook to memory stream | export chart‑enhanced Excel to byte array C# | upload Aspose.Cells generated file to Azure Blob storage | column chart data manipulation Aspose.Cells | stream‑based workbook saving Aspose.Cells .NET | cloud storage integration Aspose.Cells workbook

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Charts;   // Required for ChartType and Series classes

// The example creates a new Workbook, populates cells with month and sales data, adds a column chart titled "Monthly Sales", increases each sales value by 10%, and saves the workbook as an XLSX file. The same workflow can be adapted to write the workbook to a MemoryStream, enabling upload to cloud storage services such as Azure Blob.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook
            var workbook = new Workbook();

            // Populate worksheet with sample data for the chart
            var cells = workbook.Worksheets[0].Cells;
            cells["A1"].PutValue("Month");
            cells["B1"].PutValue("Sales");
            cells["A2"].PutValue("Jan");
            cells["A3"].PutValue("Feb");
            cells["A4"].PutValue("Mar");
            cells["B2"].PutValue(120);
            cells["B3"].PutValue(150);
            cells["B4"].PutValue(180);

            // Add a column chart to the worksheet
            int chartIdx = workbook.Worksheets[0].Charts.Add(ChartType.Column, 5, 0, 20, 10);
            var chart = workbook.Worksheets[0].Charts[chartIdx];
            chart.Title.Text = "Monthly Sales";

            // Define the series (values) for the chart
            chart.NSeries.Add("B2:B4", true);
            // Category data (months) can be set if supported; omitted here to avoid API mismatch
            // chart.NSeries[0].CategoryData = "A2:A4";

            // Example modification: increase each sales value by 10%
            for (int row = 2; row <= 4; row++) // rows 2‑4 correspond to B2‑B4
            {
                var cell = cells[$"B{row}"];
                if (cell.Value != null && double.TryParse(cell.Value.ToString(), out double original))
                {
                    cell.PutValue(original * 1.10);
                }
            }

            // Save the workbook to a local file
            string outputPath = "SalesChart.xlsx";
            workbook.Save(outputPath, SaveFormat.Xlsx);
            Console.WriteLine($"Workbook saved to {Path.GetFullPath(outputPath)}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error: {ex.Message}");
        }
    }
}
